'use strict';
const courses={
 vapt:{title:'Practical VAPT Foundations',meta:'10 weeks proposed · 40 live hours + 40 practice hours',description:'For beginners with basic computer skills and junior IT staff. Build a complete authorised assessment workflow.',topics:['Networking, Linux/Windows and HTTP fundamentals','Scope, rules of engagement and asset inventory','Vulnerability validation and access-control testing','Evidence handling, risk explanation and professional reports','Remediation verification and retesting'],outcome:'Assess a fictional small-business lab. Submit scope, an asset list, a test log, validated findings and a retest record.',note:'Academy completion assessment. Labs and final batch arrangements will be confirmed before enrolment.'},
 ethical:{title:'Ethical Hacking Foundations',meta:'12 weeks proposed · 48 live hours + 48 practice hours',description:'For learners with basic networking and operating-system knowledge. Independent foundations for further ethical-hacking study.',topics:['Threats, weaknesses, controls and scoped discovery','Credential, endpoint and network security concepts','Social engineering defences and incident response','Wireless, mobile, cloud and cryptography fundamentals','Web/API concepts and an ethical study plan'],outcome:'Build a threat-control map, evidence log and recommendations for a fictional organisation. Present a short incident-response tabletop.',note:'Independent CEH preparation only. This is not official EC-Council training or a complete vendor exam curriculum. Exam eligibility, vouchers and certification are separate.'},
 web:{title:'Web & API Security Testing',meta:'8 weeks proposed · 32 live hours + 32 practice hours',description:'For learners familiar with HTTP, Linux and basic VAPT. Develop a systematic application-testing approach.',topics:['Application mapping and role matrices','Authentication, sessions and object-level authorisation','Function/property permissions and input handling','CSRF, cross-origin policies, tokens and uploads','Business logic, coverage, reporting and retesting'],outcome:'Assess a fictional student portal with three roles. Submit an endpoint inventory, coverage sheet, validated findings and a retest.',note:'Uses assigned sandbox applications and synthetic records. No testing of public or client targets without separate authorisation.'},
 grc:{title:'GRC & ISO 27001 Fundamentals',meta:'8 weeks proposed · 32 live hours + 24 practice hours',description:'For IT staff and aspiring GRC analysts. Understand how to organise information-security implementation work.',topics:['ISMS scope, context and asset ownership','Risk criteria, assessment, treatment and acceptance','Statement of Applicability and control evidence','Policies, procedures, access and suppliers','Internal audits, corrective action and improvement'],outcome:'Build a miniature ISMS pack for a fictional SaaS company: scope, five risks, treatment plan, sample SoA and an audit finding.',note:'Implementation fundamentals only. This does not confer accredited Lead Auditor status or authority to issue ISO certificates.'}
};
const cfg=window.SECUVIDYRA_CONFIG||{};
const menu=document.querySelector('.menu'),nav=document.querySelector('.navlinks');
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});
nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));let n=0;document.querySelectorAll('.course').forEach(c=>{c.hidden=b.dataset.filter!=='all'&&!c.dataset.category.split(' ').includes(b.dataset.filter);if(!c.hidden)n++});document.querySelector('#filter-status').textContent=`Showing ${n} ${n===1?'course':'courses'}`;}));
const dialog=document.querySelector('#course-dialog');
document.querySelectorAll('[data-course]').forEach(b=>b.addEventListener('click',()=>{let key=b.dataset.course,c=courses[key];document.querySelector('#dialog-title').textContent=c.title;document.querySelector('#dialog-meta').textContent=c.meta;document.querySelector('#dialog-description').textContent=c.description;document.querySelector('#dialog-topics').replaceChildren(...c.topics.map(t=>{let li=document.createElement('li');li.textContent=t;return li}));document.querySelector('#dialog-outcome').textContent=c.outcome;document.querySelector('#dialog-note').textContent=c.note;document.querySelector('#dialog-syllabus').href=`syllabi/${key}.html`;document.querySelector('#dialog-enquire').onclick=()=>{document.querySelector('#course-choice').value=key;dialog.close()};dialog.showModal()}));
document.querySelector('.close')?.addEventListener('click',()=>dialog.close());
dialog?.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
const email=typeof cfg.admissionsEmail==='string'&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cfg.admissionsEmail)?cfg.admissionsEmail:'';
if(email){document.querySelector('#enquiry-submit').textContent='Prepare email enquiry ›';document.querySelector('#contact-note').textContent=`This form opens your email app with a draft addressed to ${email}. You review and send it there. Nothing is submitted automatically.`;}
if(/^\d{8,15}$/.test(cfg.whatsappNumber||'')){const w=document.querySelector('#whatsapp');w.hidden=false;w.href='https://wa.me/'+cfg.whatsappNumber;w.rel='noopener noreferrer';w.target='_blank';}
if(cfg.legalOperator){const o=document.querySelector('#operator');o.hidden=false;o.textContent='Operated by '+cfg.legalOperator;}
document.querySelector('#enquiry-form')?.addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;if(!f.reportValidity())return;const d=new FormData(f);const body=`SecuVidyra Academy — Course enquiry\n\nName: ${d.get('name')}\nEmail: ${d.get('email')}\nCourse: ${courses[d.get('course')].title}\nBackground and timing: ${d.get('message')||'Not specified'}\n\nPlease share confirmed batch dates, fees, prerequisites and enrolment terms.\n`;
if(email){location.href=`mailto:${encodeURIComponent(email)}?subject=${encodeURIComponent('SecuVidyra course enquiry')}&body=${encodeURIComponent(body)}`;document.querySelector('#form-status').textContent='Your email app should open with a draft. Please review and send it there. No enquiry has been submitted by this website.';}else{const url=URL.createObjectURL(new Blob([body],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='SecuVidyra-course-enquiry.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#form-status').textContent='Enquiry file prepared. It has not been sent. Keep it until the academy publishes its admissions contact.';}});
